"""Expert task and routed task commands; specs are generated by the service."""
import argparse
import asyncio
import json
import os
from pathlib import Path
from .composition import build_resources, build_live_services
from .resources.snapshots import ResourceRef
from .routing import RouteBlocked


def serial(value):
    if hasattr(value, 'model_dump'): return value.model_dump(mode='json')
    if isinstance(value, dict): return {k: serial(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)): return [serial(v) for v in value]
    return value


async def run(args):
    from .adapters.postgres import PostgresDatabase
    db = PostgresDatabase(os.environ['DATABASE_URL'])
    try:
        scopes = build_resources(db, args.blobs)
        from .routing.config import load_router
        router = load_router(args.catalog) if args.catalog else None
        from .coding.workspace import CodingService
        coding = CodingService.from_config(args.coding_config) if args.coding_config else None
        research, tasks, _ = build_live_services(db, scopes, private_root=args.private, router=router, coding=coding)
        if args.action == 'grant-code':
            from .coding.models import CodingContract
            value = tasks.grant_coding(args.research, args.name, CodingContract.model_validate_json(Path(args.file).read_text()))
        elif args.action == 'create':
            refs = tuple(ResourceRef.model_validate_json(x) for x in args.ref)
            value = tasks.create(research_id=args.research, kind=args.kind, user_request=args.request,
                goal=args.goal, required_refs=refs, required_results=tuple(args.result),
                agent_mode=args.agent_mode, role_instructions=args.role_instructions,
                authorized_refs=tuple(ResourceRef.model_validate_json(x) for x in args.authorized_ref),
                model=args.model, task_id=args.task_id,
                coding=tasks.coding_grants(args.research).get(args.coding_contract) if args.coding_contract else None)
        elif args.action == 'create-routed':
            refs = tuple(ResourceRef.model_validate_json(x) for x in args.ref)
            value = await tasks.create_routed(research_id=args.research, kind=args.kind,
                user_request=args.request, goal=args.goal, required_refs=refs,
                required_results=tuple(args.result), task_id=args.task_id,
                approved_summary=args.summary,
                preferred_expert=args.expert, preferred_model=args.model,
                budget_usd=args.budget_usd, reroute_reason=args.reroute_reason,
                coding=tasks.coding_grants(args.research).get(args.coding_contract) if args.coding_contract else None)
        elif args.action == 'run': value = await tasks.run(args.id)
        elif args.action == 'show':
            spec = tasks.spec(args.id)
            runs = tasks.query('list_runs', args.id)
            value = {'spec': spec, 'route':tasks.query('route',spec.route_id) if spec.route_id else None,
                'runs': [{'binding': r, 'execution': tasks.ledger.get(r.id),
                'receipt': tasks.query('receipt', f'task-result:{r.id}')} for r in runs]}
        elif args.action == 'route': value = tasks.query('route', args.id)
        elif args.action == 'receipt': value = tasks.receipt(args.id)
        elif args.action == 'review':
            raw = json.loads(Path(args.file).read_text())
            value = tasks.review(args.id, {int(k): (v['status'], v['evidence']) for k, v in raw.items()},args.reviewer)
        elif args.action == 'adopt': value = tasks.adopt(args.id)
        if args.action in ('run', 'review'): await tasks.learning.drain()
        print(json.dumps(serial(value), ensure_ascii=False, indent=2))
        return 0
    finally:
        if "coding" in locals() and coding is not None: coding.close()
        db.close()


def main():
    parser = argparse.ArgumentParser(description='Expert tasks, routes and receipts')
    from .cli_options import add_service_options
    add_service_options(parser)
    parser.add_argument('--coding-config', help='Operator-owned repository and trusted test profile config')
    subs = parser.add_subparsers(dest='action', required=True)
    p = subs.add_parser('create')
    p.add_argument('research'); p.add_argument('kind', choices=('search', 'extract', 'analyze', 'synthesize', 'coding'))
    p.add_argument('request'); p.add_argument('--goal'); p.add_argument('--ref', action='append', default=[])
    p.add_argument('--result', action='append', default=[]); p.add_argument('--model')
    p.add_argument('--task-id'); p.add_argument('--coding-contract')
    p.add_argument('--agent-mode', choices=('temporary','specialist'), default='specialist')
    p.add_argument('--role-instructions', default='')
    p.add_argument('--authorized-ref', action='append', default=[])
    p = subs.add_parser('create-routed')
    p.add_argument('research'); p.add_argument('kind', choices=('search', 'extract', 'analyze', 'synthesize', 'coding'))
    p.add_argument('request'); p.add_argument('--goal'); p.add_argument('--ref', action='append', default=[])
    p.add_argument('--result', action='append', default=[]); p.add_argument('--model')
    p.add_argument('--expert'); p.add_argument('--task-id'); p.add_argument('--coding-contract'); p.add_argument('--summary', required=True)
    p.add_argument('--reroute-reason')
    p.add_argument('--budget-usd', type=float, required=True)
    p = subs.add_parser('grant-code')
    p.add_argument('research'); p.add_argument('name'); p.add_argument('file')
    for name in ('run', 'show', 'route', 'receipt', 'adopt'):
        p = subs.add_parser(name); p.add_argument('id')
    p = subs.add_parser('review'); p.add_argument('id'); p.add_argument('file'); p.add_argument('--reviewer',default='local-user')
    args = parser.parse_args()
    try: raise SystemExit(asyncio.run(run(args)))
    except (KeyError, ValueError, PermissionError, RouteBlocked) as exc:
        print(f'{type(exc).__name__}: {exc}')
        raise SystemExit(1)


if __name__ == '__main__': main()
